import React from "react";
function Syllabs(){
    return(
<div className="column">
	<div className="column2">
		<img
			src={"https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/a83zr8d6_expires_30_days.png"} 
			className="image"
		/>
		<div className="absolute-view">
			<span className="text" >
				{"Everyday conversations"}
			</span>
		</div>
		<div className="absolute-view2">
			<span className="text2" >
				{"Role-playing Dialogues"}
			</span>
		</div>
		<div className="absolute-view3">
			<span className="text3" >
				{"Pronunciation Skills"}
			</span>
		</div>
		<div className="absolute-view4">
			<span className="text4" >
				{"Basic  greetings"}
			</span>
		</div>
		<div className="absolute-view5">
			<span className="text5" >
				{"Introducing  oneself"}
			</span>
		</div>
		<div className="absolute-view6">
			<span className="text6" >
				{"Forming Sentences"}
			</span>
		</div>
		<div className="absolute-view7">
			<span className="text7" >
				{"Common Vocabulary"}
			</span>
        </div>
    </div>
</div>
    );
}
export default Syllabs;
